namespace ghidra.feature.vt.gui.actions;

using static ghidra.framework.main.DataTreeDialogType;

using docking;
using docking.action;
using docking.action;
using docking.tool;
using ghidra.feature.vt.api.main;
using ghidra.feature.vt.gui.plugin;
using ghidra.feature.vt.gui.plugin;
using ghidra.framework.main;
using ghidra.framework.model;
using ghidra.framework.model;
using ghidra.framework.plugintool;
using ghidra.util;

public class OpenVersionTrackingSessionAction : DockingAction {

	private VTController controller;

	public OpenVersionTrackingSessionAction(VTController controller) : base("Open Session", VTPlugin.OWNER)
    {
		this.controller = controller;
		string[] menuPath = new string[] { ToolConstants.MENU_FILE, "Open Session..." };
		setMenuBarData(new MenuData(menuPath, "AAA"));
		setDescription("Opens a Version Tracking Session");
		setHelpLocation(new HelpLocation("VersionTrackingPlugin", "Version_Tracking_Tool"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		PluginTool tool = controller.getTool();
		DataTreeDialog dialog =
			new DataTreeDialog(tool.getToolFrame(), "Open Version Tracking Session", OPEN,
				new DefaultDomainFileFilter(typeof(VTSession), true));

		tool.showDialog(dialog);
		if (!dialog.wasCancelled()) {
			DomainFile domainFile = dialog.getDomainFile();
			controller.openVersionTrackingSession(domainFile);
		}
	}

}
